"""Actual MinIO generated bytes, renderer PID recovery and current ACL checks."""
import asyncio
import hashlib
import io
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import time
import uuid

sys.path.insert(0, '/workspace/v2/apps/backend/tests')
import psycopg
from sqlalchemy.ext.asyncio import async_sessionmaker, create_async_engine
from test_action_contracts_integration import deny

from rtr_copilot.context.models import SOTReference
from rtr_copilot.db.uow import UnitOfWork
from rtr_copilot.documents.service import DocumentOSService
from rtr_copilot.ingestion import api as files_api
from rtr_copilot.repositories.identity_postgres import PostgresSubjectRepository
from rtr_copilot.storage.s3 import S3ObjectStorage
from rtr_copilot.config import get_settings

def render_and_verify(root, identity, native_worker, *, kill_profile=False):
    root = Path(root)
    domain = os.environ['POSTGRES_DSN']
    with psycopg.connect(domain) as db:
        job = db.execute('SELECT render_job_id FROM action_source_links WHERE run_id=%s', (identity,)).fetchone()[0]
    marker = '/tmp/' + root.parent.name + '-' + root.name + '-render-marker.json'
    assert not Path(marker).exists()
    records = []
    def launch(label, pause):
        command = [sys.executable, '/work/render_child.py']
        out = (root / (label + '.stdout.txt')).open('w'); err = (root / (label + '.stderr.txt')).open('w')
        env = dict(os.environ, TIP054_RENDER_JOB=str(job), TIP054_RENDER_PAUSE='1' if pause else '0', TIP054_RENDER_MARKER=marker, DOCUMENT_RENDER_LEASE_SECONDS='10')
        child = subprocess.Popen(command, env=env, stdout=out, stderr=err)
        out.close(); err.close()
        records.append({'label': label, 'pid': child.pid, 'command': command, 'pause_after_staged_renditions': pause})
        return child
    first = launch('renderer-first', kill_profile)
    try:
        if kill_profile:
            deadline = time.monotonic() + 30
            while not Path(marker).exists() and time.monotonic() < deadline:
                assert first.poll() is None, 'renderer_failed_before_staging_pause'
                time.sleep(.05)
            assert Path(marker).exists()
            with psycopg.connect(domain) as db:
                state = db.execute('SELECT j.state,j.attempt,j.lease_token,o.state FROM render_jobs j JOIN document_publication_outbox o USING(render_job_id) WHERE j.render_job_id=%s', (job,)).fetchone()
                generated = db.execute('SELECT count(*) FROM generated_files WHERE render_job_id=%s', (job,)).fetchone()[0]
            assert state[0] == 'rendering' and state[3] == 'preparing' and generated == 0
            (root / 'renderer-before-kill.json').write_text(json.dumps({'marker': json.loads(Path(marker).read_text()), 'state': state, 'generated_files': generated}, default=str, indent=2))
            first.kill(); code = first.wait(timeout=5)
            records.append({'label': 'actual-renderer-process-kill', 'pid': first.pid, 'signal': 'SIGKILL', 'exit_code': code})
            assert code == -9
            time.sleep(10.2)  # finite source-owned lease expiry, not action-workflow lease.
            second = launch('renderer-restart', False)
            try:
                code = second.wait(timeout=30)
                records.append({'label': 'renderer-restart', 'pid': second.pid, 'exit_code': code})
                assert code == 0
            finally:
                if second.poll() is None:
                    second.kill(); second.wait(timeout=5)
            deadline = time.monotonic() + 10
            while time.monotonic() < deadline:
                with psycopg.connect(domain) as db:
                    failed = db.execute('''SELECT e.state,e.reason_code,e.spent_tool_calls,j.state,j.error_code,j.attempt,p.state,p.error_code
                        FROM action_executions e JOIN action_source_links l USING(run_id)
                        JOIN render_jobs j USING(render_job_id) JOIN document_publication_outbox p USING(render_job_id)
                        WHERE e.run_id=%s''', (identity,)).fetchone()
                    generated = db.execute('SELECT count(*) FROM generated_files WHERE render_job_id=%s', (job,)).fetchone()[0]
                    artifacts = db.execute("SELECT count(*) FROM action_execution_receipts WHERE run_id=%s AND kind='artifact_verified'", (identity,)).fetchone()[0]
                if failed[0] == 'partial':
                    break
                assert native_worker.poll() is None
                time.sleep(.1)
            assert failed[0] == 'partial' and failed[1] == 'document_render_failed'
            assert failed[3] == 'failed' and failed[4] == 'render_lease_expired'
            assert failed[6] == 'failed' and failed[7] == 'render_lease_expired'
            assert generated == artifacts == 0
            (root / 'real-render-kill-proof.json').write_text(json.dumps({'status': 'PASS', 'run_id': identity,
                'render_job_id': str(job), 'actual_source_and_business_state': failed,
                'generated_files': generated, 'artifact_receipts': artifacts,
                'interpretation': 'Existing source owner deliberately fails ambiguous expired staging. Executor reports useful partial/document_render_failed, never a fabricated file or blind redispatch.'}, default=str, indent=2))
            return
        code = first.wait(timeout=30)
        records.append({'label': 'renderer-normal-complete', 'pid': first.pid, 'exit_code': code})
        assert code == 0
        deadline = time.monotonic() + 20
        while time.monotonic() < deadline:
            with psycopg.connect(domain) as db:
                final = db.execute('SELECT state,spent_tool_calls FROM action_executions WHERE run_id=%s', (identity,)).fetchone()
                row = db.execute('''SELECT g.generated_file_id,g.version_id,g.checksum,j.state,j.attempt,
                    p.state,o.object_key,o.sha256,o.byte_size,r.classification
                    FROM generated_files g JOIN render_jobs j USING(render_job_id)
                    JOIN document_publication_outbox p USING(render_job_id)
                    JOIN object_blobs o ON o.object_id=g.object_id
                    JOIN resources r ON r.resource_id=g.version_id WHERE j.render_job_id=%s''', (job,)).fetchone()
                artifacts = db.execute("SELECT count(*) FROM action_execution_receipts WHERE run_id=%s AND kind='artifact_verified'", (identity,)).fetchone()[0]
            if final[0] == 'succeeded' and artifacts == 1 and row is not None:
                break
            assert native_worker.poll() is None, 'native_worker_exited_before_file_receipt'
            time.sleep(.1)
        else:
            raise AssertionError('native_source_verified_artifact_not_reached')
        assert row[3] == 'completed' and row[5] == 'finalized' and row[2] == row[7]
        assert row[4] == 1
        async def content_and_acl():
            from docx import Document
            engine = create_async_engine(domain.replace('postgresql://', 'postgresql+asyncpg://', 1))
            factory = async_sessionmaker(engine, expire_on_commit=False)
            seed = json.loads((root / 'seed.json').read_text())
            actor = await PostgresSubjectRepository(factory).get_by_user_id(uuid.UUID(seed['actor_id']))
            assert actor is not None
            try:
                service = DocumentOSService(UnitOfWork(factory))
                await service.generated_detail(actor, row[0], request_id='native-generated-before-revoke')
                permitted = await files_api._version_authorized(actor, row[1], action='download', request_id='native-download-before-revoke')
                assert permitted is not None and permitted[1]
                payload = io.BytesIO()
                await S3ObjectStorage(get_settings()).download_to(row[6], payload)
                data = payload.getvalue()
                sha = hashlib.sha256(data).hexdigest()
                assert sha == row[2] and len(data) == row[8]
                assert 'Synthetic native fixture' in '\n'.join(p.text for p in Document(io.BytesIO(data)).paragraphs)
                reference = SOTReference.model_validate_json(json.dumps(seed['source_refs'][0]))
                await deny(factory, reference, actor)
                forbidden = await files_api._version_authorized(actor, row[1], action='download', request_id='native-download-after-revoke')
                assert forbidden is None or not forbidden[1]
                try:
                    await service.generated_detail(actor, row[0], request_id='native-generated-after-revoke')
                except (LookupError, ValueError):
                    denied_detail = True
                else:
                    denied_detail = False
                assert denied_detail
                return {'byte_size': len(data), 'sha256': sha, 'docx_text_oracle': True, 'download_permitted_before_revoke': True, 'download_denied_after_source_revoke': True, 'generated_detail_denied_after_source_revoke': True}
            finally:
                await engine.dispose()
        verified = asyncio.run(content_and_acl())
        (root / 'real-file-proof.json').write_text(json.dumps({'status': 'PASS', 'run_id': identity, 'render_job_id': str(job), 'generated_file_id': str(row[0]), 'version_id': str(row[1]), 'source_render_attempts': row[4], 'business_spent_tool_calls': final[1], 'finalized_source': True, 'content_and_acl': verified, 'source_classification': row[9], 'limits': 'Actual synthetic MinIO DOCX/files/render pipeline and current source-policy guards; deterministic synthetic clean scanner, not malware/security/format-quality/production certification.'}, indent=2))
    finally:
        if first.poll() is None:
            first.kill(); first.wait(timeout=5)
        (root / 'renderer-process-records.json').write_text(json.dumps(records, indent=2))
